begin
  -- torquedrag / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'torquedrag' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w4a torquedrag refused: torquedrag/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e668c5a5e475d056bdc04645b9e2b8f8' and fields = '[{"key": "buoyancy_factor_1500", "tol": 5E-7, "unit": "-", "label": "Buoyancy factor at 1500 kg/m3", "expected": 0.8089171974522293}, {"key": "vertical_hookload_N", "tol": 0.5, "unit": "N", "label": "Vertical well hookload", "expected": 725456.7587525246}, {"key": "slant_pickup_hookload_N", "tol": 0.5, "unit": "N", "label": "Slant well pick up", "expected": 1093364.404907054}, {"key": "slant_slackoff_hookload_N", "tol": 0.5, "unit": "N", "label": "Slant well slack off", "expected": 598767.1689649521}, {"key": "slant_drag_swing_N", "tol": 0.5, "unit": "N", "label": "Slant well total drag swing", "expected": 494597.2359421019}, {"key": "horizontal_slackoff_hookload_N", "tol": 0.5, "unit": "N", "label": "Horizontal well slack off", "expected": -16520.58505864785}]'::jsonb then 'old'
