  if v_n <> 1 then raise exception 'w4a torquedrag refused: torquedrag/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '9caa243e5bf72ba3650dd567029ee9d6' and fields = '[{"key": "buildhold_rot_torque_Nm", "tol": 0.05, "unit": "N.m", "label": "Build and hold rotating torque", "expected": 26687.478922047892}, {"key": "horizontal_rot_torque_Nm", "tol": 0.05, "unit": "N.m", "label": "Horizontal rotating torque", "expected": 24154.471040113644}, {"key": "buildhold_max_side_force_Npm", "tol": 0.005, "unit": "N/m", "label": "Build and hold max side force", "expected": 1156.5832934561317}, {"key": "swell3d_backream_torque_Nm", "tol": 0.05, "unit": "N.m", "label": "3D turn back-reaming torque", "expected": 15232.475119527086}, {"key": "horizontal_slide_min_tension_N", "tol": 0.5, "unit": "N", "label": "Horizontal slide min tension", "expected": -419384.71820713475}, {"key": "buildhold_mu_for_1100kN_pickup", "tol": 0.0005, "unit": "-", "label": "Fitted open-hole friction factor", "expected": 0.4102238555495764}]'::jsonb then 'old'
              when md5(prompt) = '8f00ff2ba05924fb184694291145e83c' and fields = '[{"key": "buildhold_rot_torque_Nm", "tol": 0.05, "unit": "N.m", "label": "Build and hold rotating torque", "expected": 26687.478922047892}, {"key": "horizontal_rot_torque_Nm", "tol": 0.05, "unit": "N.m", "label": "Horizontal rotating torque", "expected": 24154.471040113644}, {"key": "buildhold_max_side_force_Npm", "tol": 0.005, "unit": "N/m", "label": "Build and hold max side force", "expected": 1156.5832934561317}, {"key": "swell3d_backream_torque_Nm", "tol": 0.05, "unit": "N.m", "label": "3D turn back-reaming torque", "expected": 15232.475119527086}, {"key": "horizontal_slide_min_tension_N", "tol": 0.5, "unit": "N", "label": "Horizontal slide min tension", "expected": -419384.71820713475}, {"key": "buildhold_mu_for_1100kN_pickup", "tol": 0.0005, "unit": "-", "label": "Fitted open-hole friction factor", "expected": 0.4102238555495764}]'::jsonb then 'new'
