  if v_n <> 1 then raise exception 'w4a torquedrag refused: torquedrag/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'bba3c319d960fb2b6474800a76fbc0c7' and fields = '[{"key": "dp_sinusoidal_limit_90deg_N", "tol": 0.5, "unit": "N", "label": "Sinusoidal buckling limit", "expected": 170426.18707539304}, {"key": "dp_helical_limit_90deg_N", "tol": 0.5, "unit": "N", "label": "Helical buckling limit", "expected": 311611.86321571725}, {"key": "hz_max_torsion_utilization", "tol": 0.00005, "unit": "-", "label": "Worst torsion utilization", "expected": 0.24042492498112686}, {"key": "casing_sliding_distance_m", "tol": 0.5, "unit": "m", "label": "Total sliding distance", "expected": 199830.26842990686}, {"key": "casing_max_wear_depth_mm", "tol": 0.0005, "unit": "mm", "label": "Worst casing wear depth", "expected": 3.537607641481055}, {"key": "casing_worst_wall_loss_pct", "tol": 0.005, "unit": "percent", "label": "Worst wall loss", "expected": 29.507604109511}]'::jsonb then 'old'
              when md5(prompt) = '7c4f728e9bbf7b5cb7d17c43bc3485f5' and fields = '[{"key": "dp_sinusoidal_limit_90deg_N", "tol": 0.5, "unit": "N", "label": "Sinusoidal buckling limit", "expected": 170426.18707539304}, {"key": "dp_helical_limit_90deg_N", "tol": 0.5, "unit": "N", "label": "Helical buckling limit", "expected": 311611.86321571725}, {"key": "hz_max_torsion_utilization", "tol": 0.00005, "unit": "-", "label": "Worst torsion utilization", "expected": 0.24042492498112686}, {"key": "casing_sliding_distance_m", "tol": 0.5, "unit": "m", "label": "Total sliding distance", "expected": 199830.26842990686}, {"key": "casing_max_wear_depth_mm", "tol": 0.0005, "unit": "mm", "label": "Worst casing wear depth", "expected": 3.537607641481055}, {"key": "casing_worst_wall_loss_pct", "tol": 0.005, "unit": "percent", "label": "Worst wall loss", "expected": 29.507604109511}]'::jsonb then 'new'
